// Solo se acepta un UUID; el resto de los datos se lee de Supabase
const b = $input.first().json.body || $input.first().json;
const id = String(b.captacion_id || '').trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) return [];
return [{ json: { id } }];

// ===== CONFIGURA AQUÍ =====
const WA_API_URL = 'https://evolution.maximusinmobiliaria.tech'; // URL de tu Evolution API (sin / al final)
const WA_INSTANCIA = 'maximus';                                   // nombre de la instancia conectada
const URL_DASHBOARD = 'https://maximusinmobiliaria.tech/dashboard';
// ==========================
// Si la solicitud ya se había notificado, Supabase devuelve [] y aquí no sale nada
return $input.all().map(i => i.json).filter(c => c && c.id).map(c => {
const OPER = { venta: 'VENDER', alquiler: 'ALQUILAR (poner en alquiler)', compra: 'COMPRAR' };
const oper = OPER[c.operacion] || c.operacion;
const primerCliente = String(c.nombre || '').split(' ')[0];
const primerAsesor = String(c.asesor_nombre || '').split(' ')[0];
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));

const linkCliente = `https://wa.me/${c.whatsapp}?text=${encodeURIComponent(`Hola ${primerCliente}, soy ${c.asesor_nombre} de MAXIMUS Inmobiliaria. Recibí tu solicitud ${c.codigo} para ${oper.toLowerCase()} ${c.tipo_inmueble} en ${c.zona}. ¿Tienes un momento para conversar?`)}`;

const textoAsesor = [
  `🏠 *Nueva solicitud MAXIMUS* · ${c.codigo}`,
  c.es_equipo_maximus ? '_(No había asesores Platinum en cola: va al equipo MAXIMUS)_' : `Te tocó en la cola Platinum, ${primerAsesor}.`,
  '',
  `👤 *Cliente:* ${c.nombre}`,
  `📱 *WhatsApp:* +${c.whatsapp}`,
  `🔑 *Quiere:* ${oper}`,
  `🏷️ *Tipo:* ${c.tipo_inmueble}`,
  `📍 *Zona:* ${c.zona}`,
  c.precio_estimado ? `💵 *Precio aprox.:* ${c.precio_estimado}` : null,
  c.comentario ? `📝 *Comentario:* ${c.comentario}` : null,
  '',
  `👉 Escríbele ya: ${linkCliente}`
].filter(l => l !== null).join('\n');

const textoCliente = [
  `Hola ${primerCliente} 👋, recibimos tu solicitud en *MAXIMUS Inmobiliaria* (${c.codigo}).`,
  `Tu asesor asignado es *${c.asesor_nombre}* y te escribirá muy pronto por este medio.`,
  `Si prefieres adelantarte, escríbele aquí: https://wa.me/${c.asesor_whatsapp}`
].join('\n');

const html = `<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;border:1px solid #E5E7EB;border-radius:16px;overflow:hidden">
<div style="background:#0B4A3F;color:#fff;padding:20px 24px"><b style="font-size:18px">MAXIMUS<span style="color:#10B981">.</span></b><br><span style="font-size:12px;color:#CBD5E1">Nueva solicitud · ${esc(c.codigo)}</span></div>
<div style="padding:24px;color:#111827;font-size:14px;line-height:1.6">
<p>Hola ${esc(primerAsesor)}, ${c.es_equipo_maximus ? 'esta solicitud llegó al equipo MAXIMUS.' : 'te tocó esta solicitud en la cola Platinum.'}</p>
<p><b>Cliente:</b> ${esc(c.nombre)}<br><b>WhatsApp:</b> +${esc(c.whatsapp)}<br><b>Quiere:</b> ${esc(oper)}<br><b>Tipo:</b> ${esc(c.tipo_inmueble)}<br><b>Zona:</b> ${esc(c.zona)}${c.precio_estimado ? `<br><b>Precio aprox.:</b> ${esc(c.precio_estimado)}` : ''}${c.comentario ? `<br><b>Comentario:</b> ${esc(c.comentario)}` : ''}</p>
<p style="text-align:center;margin:24px 0"><a href="${linkCliente}" style="background:#25D366;color:#fff;text-decoration:none;padding:12px 22px;border-radius:10px;font-weight:bold">Escribirle por WhatsApp</a></p>
<p style="font-size:12px;color:#6B7280">Panel: <a href="${URL_DASHBOARD}">${URL_DASHBOARD}</a></p>
</div></div>`;

return {
  json: {
    ...c,
    wa_url_envio: `${WA_API_URL}/message/sendText/${WA_INSTANCIA}`,
    texto_asesor: textoAsesor,
    texto_cliente: textoCliente,
    asunto: `🏠 Nueva solicitud ${c.codigo}: ${c.nombre} quiere ${oper.toLowerCase()} (${c.zona})`,
    html,
    tiene_email: /@/.test(String(c.asesor_email || ''))
  }
};
});
